const http = require('http');

const port = process.env.PORT || 8080;

const professional = {
  professionalName: 'Dennis Awuah',
  base64Image:
    '',
  nameLink: {
    firstName: 'Dennis',
    url: 'https://github.com/Awuah166',
  },
  primaryDescription: ' is a software developer who enjoys building useful web applications.',
  workDescription1:
    'I enjoy solving practical problems with clean, maintainable code and thoughtful user experiences.',
  workDescription2:
    'This API provides the professional information displayed by the frontend.',
  linkTitleText: 'Connect with me:',
  linkedInLink: {
    text: 'LinkedIn',
    link: 'https://www.linkedin.com/',
  },
  githubLink: {
    text: 'GitHub',
    link: 'https://github.com/Awuah166',
  },
};

const server = http.createServer((request, response) => {
  response.setHeader('Access-Control-Allow-Origin', '*');

  if (request.method === 'GET' && request.url === '/professional') {
    response.writeHead(200, { 'Content-Type': 'application/json' });
    response.end(JSON.stringify(professional));
    return;
  }

  response.writeHead(404, { 'Content-Type': 'application/json' });
  response.end(JSON.stringify({ error: 'Route not found' }));
});

server.listen(port, '0.0.0.0', () => {
  console.log(`API server running at http://localhost:${port}`);
});